/bin/bash -lc "cat <<'EOF' > /vercel/sandbox/app/data/posts.ts
import \"server-only\";

import { unstable_cache } from \"next/cache\";

export type Post = {
  id: number;
  title: string;
  body: string;
  createdAt: string;
};

let posts: Post[] = [];
let nextId = 1;

export function addPost(input: { title: string; body: string }): Post {
  const post: Post = {
    id: nextId++,
    title: input.title,
    body: input.body,
    createdAt: new Date().toISOString(),
  };

  posts.unshift(post);
  return post;
}

function readPosts(): Post[] {
  return posts;
}

export const getPosts = unstable_cache(
  async () => {
    const current = readPosts();
    return current.map((post) => ({ ...post }));
  },
  [\"posts\"],
  { tags: [\"posts\"] }
);
EOF"

